-- 15/11/2026 — Cidades e locais de Acordo, Conti e Filanti; mares, lagos e recifes.
--
-- Usuário: "No reino de Acordo, falta Coberae, Pratissi. No reino de conti falta
-- Florestas de Melgundi, Condado Élfico de Lirati, Ruínas Moldazi. No reino
-- Filanti falta Verda, Pacri, Florestas de Girondi, Fétor." e "Falta também Mar
-- da Morte, Mar Gelado, etc." Mares entram como LOCAIS: "Localidades, inclusive
-- Mar do Norte e Lago Denégrio são locais." A Ilha dos Corvos, cidade do reino
-- Lago Denégrio, "vira local também".
-- Fonte: tagmar/reinos.pdf (3.11 Acordo, 3.13 Filanti, 3.14 Conti) e
-- tagmar/ambientacao.pdf (mares); o Mar Gelado e o Estreito das Serpentes só
-- existem no mapa, e o texto deles diz só onde ficam.
-- Idempotente: ON CONFLICT (slug) DO NOTHING; a capital só entra se vazia.

BEGIN;

-- ── acordo (novo-reino-h24-f00c2479) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$palom$t$, $t$Palom$t$, $t$novo-reino-h24-f00c2479$t$, false, NULL, NULL, $t$Maira Mon, como em todas as minas do reino$t$, $t$A maior produtora de ferro de Acordo. O minério desce pelo Rio Sul até Porto Áureo.$t$, $t$Cidadela incrustada na montanha, logo na entrada da Cordilheira de Sotopor. Depois da capital, é onde humanos e anões mais se misturam.
Cercada de minas, Palom não para: as turmas se revezam em três turnos, dia e noite, o ano inteiro, e só descansam nos dias santos. A milícia é fraca. Por ficar no começo da cordilheira, a cidade nunca sofreu uma grande investida das criaturas de Abadom, mas o perigo está sempre ali.$t$, NULL, false),
($t$coberae$t$, $t$Coberae$t$, $t$novo-reino-h24-f00c2479$t$, false, NULL, NULL, $t$Maira Mon, como em todas as minas do reino$t$, $t$A maior extratora de cobre e a segunda de ferro do reino, e a que mais faz armas. Os mestres ferreiros anões daqui e das vilas próximas armam todas as cidades de Acordo e vendem para Plana, Calco e Conti.$t$, $t$Cidadela incrustada na montanha, como Palom, no meio da Cordilheira de Sotopor e bem a leste, quase na divisa com Plana. É a cidadela mais afastada do reino, e por isso a que mais comercia por terra com os planenses.
Tem a segunda milícia mais numerosa e mais bem armada de Acordo. A região em volta é pouco explorada, por causa das criaturas mortais que vivem na cordilheira.$t$, $t$Dizem pelo reino que boa parte do metal das armas do mundo sai de Acordo, e de Coberae em especial.$t$, false),
($t$minas-mon$t$, $t$Minas Mon$t$, $t$novo-reino-h24-f00c2479$t$, false, NULL, NULL, $t$Maira Mon, que deu nome à cidade$t$, $t$A maior produtora de ouro do reino, talvez do Mundo Conhecido. Todo o ouro vai para a Casa Real da Moeda, em Porto Áureo.$t$, $t$Uma cidade inteira debaixo da terra, quase no centro da Cordilheira de Sotopor. Os anões a batizaram em honra de Maira Mon quando acharam ali o maior veio de ouro do reino. Mais de oito em cada dez moradores são anões, porque poucos humanos aguentam passar a vida sob a pedra.
Do veio principal saem minas que correm por dezenas de quilômetros, cada vez mais fundo. Pela riqueza e pela vizinhança de terrores profundos, tem a maior e mais bem armada milícia do reino, e é uma das maiores fortalezas anãs deste lado do mundo.$t$, $t$Dizem que nas galerias mais fundas, aonde só os anões mais velhos chegam, há veios de metais raros, talvez mágicos, que dão armas e armaduras de dureza sem igual.$t$, false),
($t$pratissi$t$, $t$Pratissi$t$, $t$novo-reino-h24-f00c2479$t$, false, NULL, NULL, NULL, $t$A maior extratora de prata do reino, com muitas minas ao norte do Minguante de Mon. Seus armeiros fazem desde cotas de malha finíssimas até armaduras de placas completas, e escudos com os brasões das famílias nobres e da Casa Real.$t$, $t$Cidade no sopé de uma grande montanha, numa parte calma da Cordilheira de Sotopor. A prata que tira da terra segue para Porto Áureo, e as armaduras que forja vestem a nobreza de Acordo.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;

-- ── conti (novo-reino-h24-a3565606) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$muli$t$, $t$Muli$t$, $t$novo-reino-h24-a3565606$t$, true, NULL, $t$Corinos Mendrie, Lorde-Prefeito e Senhor das Armas; o Rei Arrab III governa do Castelo Moldam$t$, $t$Ganis, a Venerada Mãe, com a Catedral dos Mares$t$, $t$O maior porto do Mundo Conhecido. Os mercadores da Nobreza Mercantil mandam navios a Calco, a Plana e às Ilhas Independentes, e contratam aventureiros como marinheiros.$t$, $t$Capital de Conti e a segunda cidade construída pelos Moldas. Perto de três quintos do povo do reino vivem aqui, numa cidade enorme e suja, onde favelas se amontoam ao lado da Catedral dos Mares, do Castelo Moldam e do Distrito Antigo, encravado em encostas escarpadas.
São nove distritos: o Real, o Antigo (com sua parte religiosa, a administrativa e a de moradia), o Portuário, o Cemitério e cinco de favelas, onde vive a gente pobre. A cidade é famosa pela violência e por um sem-número de guildas de ladrões, prontas a roubar e matar por quem pagar mais.
Aqui fica a Academia Muliense de Magia, de que Del Sardeim é Diretor de Honra, e também a velha Academia de Moldazi, trazida para cá depois da queda daquela cidade. Muli é perigosa, mas guarda segredos, tesouros e tumbas que o tempo atravessou sem que ninguém tocasse.$t$, $t$O povo acredita há muito que Plana quer tirar Arrab III do trono e pôr no lugar o insosso Corinos, primo do conselheiro Celsius Mendrie. Celsius responde com piadas e põe o cargo à disposição do rei.
Entre os grandes mercadores se esconderia a Câmara Negra, que contrabandeia escravos, mercadoria roubada e drogas capazes de tirar a vontade de quem as usa. E nos becos se fala de um Rei do Crime que quer todas as guildas sob o seu nome; ninguém sabe onde está nem que rosto tem.$t$, false),
($t$ambernita$t$, $t$Ambernita$t$, $t$novo-reino-h24-a3565606$t$, false, NULL, $t$Um Lorde-Prefeito eleito pelos grandes donos de terra do sul e aceito pela coroa$t$, $t$Ganis, a Dama do Lago, no Templo da Dama$t$, $t$Produz boa parte da comida do reino, sobretudo para o sul, mas está em plena decadência.$t$, $t$A capital do sul de Conti, de porte médio, dividida entre a Nobreza Mercantil, que repartiu as terras do sul, e as velhas tradições de Moldazi. Foi erguida a oeste das ruínas pelos que abandonaram aquela cidade.
Só tem três construções de nome: o Templo da Dama, em honra de Ganis; a Casa da Memória, que guarda as tradições de Moldazi e dos antigos moldas; e a Torre do Denégrio, castelo mais velho que a cidade, que já foi quartel das tropas da região. Ambernita perde a própria cara e alimenta um rancor contra o norte que incomoda a coroa.$t$, $t$A Ordem de Ganis de Muli tenta tomar o Templo da Dama e acha excessiva a crendice do sul em torno da Grande Mãe; Ambernita vê nisso mais um ataque do norte. Há quem fale de homens prontos a tomar o sul e partir o reino ao meio, e o Grão-Mestre da Casa da Memória não esconde que quer ver os moldazianos mandando na cidade outra vez.$t$, false),
($t$pontalina$t$, $t$Pontalina$t$, $t$novo-reino-h24-a3565606$t$, false, NULL, $t$Um prefeito escolhido pelo conselho dos pequeninos mais velhos$t$, $t$Mon, Sevides e, acima de todos, Ganis, a quem temem como a sereia do lago$t$, $t$Cultiva frutas e vende para Muli a pouca lã de dozecórneo que produz.$t$, $t$Pequena vila de pequeninos à beira do Denégrio, escondida entre as colinas baixas que margeiam o lago. Fica longe das brigas entre Ambernita e os senhores de terra, e vive em paz.
Os pequeninos são receptivos e desconfiados ao mesmo tempo: a vila foi erguida entre tragédias e lutas contra feras. Todos conhecem o sul de ponta a ponta e são ótimos guias, mas evitam as ruínas dos moldas e as terras sombrias que foram de Moldazi.$t$, NULL, false),
($t$virena$t$, $t$Virena$t$, $t$novo-reino-h24-a3565606$t$, false, NULL, $t$Baldum de Virena, Príncipe Anão, o primeiro e único, escolhido pelo Conselho dos Clãs$t$, $t$Maira Mon e Blator; Parom é lembrado pelos artífices$t$, $t$A principal fornecedora de metal, armas e gemas de Muli.$t$, $t$A maior terra de anões do norte depois de Acordo. Antes se chamava Minas de Virena e era repartida entre os clãs ligados a Saravossa; só virou cidade quando aceitou o domínio de Muli. Muli não admitiu um rei, e por isso quem governa é um príncipe.
Virena ainda está sendo construída e é um eterno canteiro. Os anões guardam o planalto central de Conti ao lado dos humanos, nos Martelos Vermelhos de Virena, e evitam o sul por causa da Floresta de Melgundi. No planalto vizinho vive Malzir de Parom, sacerdote anão renegado que fugiu das minas por não aceitar a aproximação dos clãs com os mercadores; ele só trabalha para quem lhe prova o valor, de preferência numa aventura perigosa.$t$, $t$Os Martelos Vermelhos acharam pedras preciosas nas colinas de Melgundi, e Virena procura um caminho seguro até elas.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-melgundi$t$, $t$Floresta de Melgundi$t$, $t$novo-reino-h24-a3565606$t$, NULL, $t$Mata densa no centro de Conti que, junto com as Montanhas de Virena, separa o norte do sul do reino. É terra autônoma, defendida pelos elfos de Lirati e habitada por criaturas estranhas e malignas, algumas bem inteligentes. Os anões fogem dela; os rastreadores do sul são os únicos que se embrenham ali.
Os elfos lutam contra essas criaturas e contra os humanos que contrabandeiam a lingolie e destroem a mata.$t$, $t$Os Martelos Vermelhos de Virena acharam pedras preciosas nas colinas arborizadas da floresta.$t$, false),
($t$condado-elfico-de-lirati$t$, $t$Condado Élfico de Lirati$t$, $t$novo-reino-h24-a3565606$t$, NULL, $t$Vale escondido dentro da Floresta de Melgundi, lar dos elfos que fugiram da queda de Saravos, mais antigo que a chegada dos Moldas ao Vale do Frefo. A vila é de porte médio e foi erguida em grande parte no alto de árvores milenares e gigantescas.
É governada por um conde, que nunca ousou se chamar rei em respeito à antiga dinastia élfica do Segundo Ciclo. Hoje o título é de Essalie, filho de Guindam e neto de Güindor, herói daquele tempo. Os elfos de Lirati lutaram ao lado dos moldas e aceitaram Saravossa em troca de uma autonomia que nunca foi quebrada.
Cultuam sobretudo Palier, a quem devem a sobrevivência depois da queda de Saravos. Evitam o norte da floresta, perto de Virena, porque detestam os anões de lá.$t$, $t$Dizem que o vale fica escondido por magia.$t$, false),
($t$ruinas-de-moldazi$t$, $t$Ruínas de Moldazi$t$, $t$novo-reino-h24-a3565606$t$, NULL, $t$A primeira cidade dos Moldas, erguida em 212 D.C., no sul de Conti. Há muitas ruínas da velha Moldânia pela região, mas nenhuma assusta tanto pelo tamanho e pela aura.
Seus moradores eram devotos de Blator e criaram a Escola da Guerra; tomados pela sede de sangue e pela cobiça, mandaram no trono de Saravossa por muitos anos. Na guerra civil que partiu o Grande Reino da Moldânia em dois, a cidade foi arrasada pelas tropas leais ao sul e por uma peste mágica, e o povo a abandonou para fundar Ambernita mais a oeste. Parte dela ficou de pé, tomada pelo mato e pelas feras.
Os sulistas a têm por amaldiçoada e fazem rodeio para não passar perto. Há cinco anos a Academia de Moldazi, em Muli, manda grupos de aventureiros estudar as ruínas: dos cinco grupos, nenhum voltou.$t$, $t$Vultos e assombrações andam pelos vilarejos próximos, e sábios acham que algo se mexe nas profundezas das ruínas. A Academia forma o segundo grupo do ano para descobrir o quê. Foram vistos batedores estrangeiros no sul, talvez de Filanti, e há quem tema demonistas.$t$, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$muli$t$ WHERE slug = $t$novo-reino-h24-a3565606$t$ AND capital IS NULL;

-- ── filanti (novo-reino-h24-d5e5e848) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$chats$t$, $t$Chats$t$, $t$novo-reino-h24-d5e5e848$t$, true, NULL, $t$Rei Mar II, com o conselheiro Lorde Ludur$t$, $t$Blator, com o Sumo Sacerdote Lorak$t$, $t$Nos bons tempos, tudo o que existia em Tagmar se achava em suas muralhas. Hoje o comércio cai e os preços sobem.$t$, $t$Capital e cidade mais importante de Filanti, chamada de cidade branca pelas torres e alamedas de mármore alvíssimo, tirado de minas debaixo da própria cidade. Foi erguida com toda a grandeza de uma capital de reino, cheia de tabernas, hospedarias, ferreiros, coureiros e ourives.
O desgaste já aparece. As ruas largas, antes limpas e iluminadas, estão maltratadas, e em vários bairros a noite cai sem uma luz acesa. A nobreza não consegue esconder a decadência.
Chats é o quartel dos Cavaleiros Brancos, a cavalaria de elite de Filanti, comandada por Sir Malcaom. Mesmo eles são hoje sombra de um passado de glórias.$t$, $t$Corre com muito cuidado que o clero de Blator na cidade branca está corrompido, e que o Sumo Sacerdote é mais um fantoche de Ludur.$t$, false),
($t$fetor$t$, $t$Fétor$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Conde Eldor$t$, NULL, $t$Vive do Rio Lara: manda especiarias de barco às aldeias ribeirinhas, rega as lavouras e pesca.$t$, $t$A cidade mais isolada de Filanti, a noroeste da capital, entre as fronteiras de Portis, das Cidades-Estado e a Cordilheira de Keiss. Leva o nome do rei Fétor I, filho de Filam, que nasceu e foi sepultado aqui.
O Conde Eldor é um homem duro, franco e sem piedade, forjado na guerra contra os orcos de Keiss que atacam as vilas do condado. Também guarda a fronteira com Portis, e mantém na cidade 150 Cavaleiros Brancos, cavalaria de que ele mesmo fez parte.
Fétor paga os tributos e cumpre as obrigações com a corte, e nada mais: há anos ninguém vê um enviado de Chats dentro dos seus muros. Das dezenas de tabernas, as mais conhecidas são a Taberna do Rio e O Orco Fujão.$t$, NULL, false),
($t$agrapia$t$, $t$Agrápia$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Conde Deric Vermom$t$, NULL, $t$Vive da lavoura, do comércio e da caça. Seus caçadores são os melhores do reino e são contratados até para serviços estranhos.$t$, $t$Foi o principal foco de resistência na guerra da Seita e ainda traz as cicatrizes do domínio bankdi. O povo vive tempos de mudança: há menos de um ano o rei depôs o velho conde, Gevar, e Deric Vermom, nobre da corte de Portis, virou conde ao casar com Talindra, jovem sobrinha de Mar II.
Vermom é jovem e impetuoso, trata a condessa com desprezo e passa as noites em conselho com Sagor, comandante da guarda. O que lhe tira o sono é Adam, o Sombra, ladrão que ataca a qualquer hora e some sem deixar rastro. Ele mata nobres e grandes mercadores, e quem tentar detê-lo, mas nunca fere mulher nem criança. Um Cavaleiro Branco mandado de Chats para pegá-lo virou mais uma de suas vítimas, e a recompensa pela cabeça dele não para de subir.$t$, NULL, false),
($t$pacri$t$, $t$Pacri$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Visconde Lorreti$t$, NULL, $t$Cidade de comércio, que cresce na esteira de Capela e vende pelo Lago Denégrio às cidades da costa, de Filanti e de outros reinos.$t$, $t$Cidade próspera à beira do Denégrio. O Visconde Lorreti tem o apoio de Sir Malcaom, comandante dos Cavaleiros Brancos, parente da sua família.
Há quase um ano, Lorreti foi a Chats casar a filha com um nobre da capital e ficou por lá uns dois meses. Na volta, o seu conselheiro, Lorde Euridi, tinha se trancado numa torre da própria família e não recebe ninguém desde então. Em certas noites ouvem-se cânticos e gritos lá de dentro. Muitos acham que Euridi amava a filha do visconde e enlouqueceu de não ter pedido a mão dela.$t$, $t$Dizem que Euridi passa os dias estudando um velho livro de necromancia, achado nos porões do castelo, e prepara a vingança contra Lorreti e a filha.$t$, false),
($t$povariana$t$, $t$Povariana$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Marquês Délcio De Marco$t$, NULL, $t$Cidade de mercadores e caravanas. Uma vez por mês a Grande Feira toma a rua principal e enche as tabernas e estalagens com gente de todo o reino.$t$, $t$No centro de Filanti, passagem obrigatória de quem vai atravessar a Cordilheira de Keiss. Tem boas estradas para Chats e para as cidades do sul.
O Marquês Délcio De Marco veste cores berrantes e chapéus de plumas, e o povo o respeita por ser justo. Os problemas são os salteadores, que aproveitam os dias de feira para atacar as caravanas, e os orcos de Keiss, que caem sobre quem segue para o leste. Por isso é comum contratar aventureiros como escolta, já que as patrulhas de anões nas trilhas nem sempre aparecem.$t$, NULL, false),
($t$capela$t$, $t$Capela$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Barão Faliasto$t$, $t$Palier, com Vestiano Féx e Márcio Altarco; Maira Nil, num templo de Lupina Ciprene nos arredores$t$, $t$Um dos melhores portos do Denégrio e um comércio que só cresce. Os estudiosos da cidade pagam expedições semanais, organizadas na Lança Forte e no Orco Morto, para repor ingredientes mágicos.$t$, $t$A cidade mais rica e influente da região. O único desafio do Barão Faliasto são os piratas do Denégrio, e para eles há uma frota de três navios, comandada por Sifrad Elério, que chegou de Lutrúcia depois de brigar com os governantes de lá por causa de saques.
O povo é muito variado, e há mais de vinte tabernas; as preferidas dos viajantes são a Lança Forte, o Orco Morto, o Caneco de Honra e a Gargantas e Garfos, boas de comida, de bebida e de boato.
Dois sacerdotes de Palier, Vestiano Féx e Márcio Altarco, já trouxeram mortos recentes de volta à vida em público, e ganharam o povo. A bela Lupina Ciprene mantém um templo de Maira Nil fora da cidade e foge de quem não é da sua fé.$t$, $t$Os piratas do Denégrio viveriam numa cidade escondida nas reentrâncias dos Montes Palomares.
Há quem diga que a Seita tem gente em Capela procurando lugar para uma base, e que os dois sacerdotes de Palier são dela: teriam trocado poções de cura de Lupina por veneno e perseguido a sacerdotisa quase até a morte, e ela só ficou na região para se vingar. Também se diz que Maltus Tal, dono do Orco Morto, é um orco exilado disfarçado por um ilusionista, e que o anel entalhado que nunca tira tem a ver com isso.$t$, false),
($t$mutina$t$, $t$Mutina$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, NULL, $t$Maira, com a secular Catedral da Tríade$t$, NULL, $t$Uma das cidades mais estranhas da região: uma lagoa de água mineral quente a mantém sempre morna e sob uma névoa fina, e o palácio do governante fica numa ilha no meio dela. É famosa pela Catedral da Tríade, de Maira. Por estar perto de Gironde, tem mais elfos que as vizinhas.
Metade dos pequeninos da cidade são ladrões da Guilda do Metro, fundada e ainda comandada por Sobrao Larda, que dizem ter mais de duzentos anos. Um membro fugido da guilda vive sob a proteção do sábio Alarco Manhão Sul, em troca do que sabe sobre os tesouros de Larda. Alarco já sofreu doze atentados na sua torre no centro da cidade; no pior, o dono da velha taberna Caneco de Carvalho tentou envenená-lo, e a briga pôs o lugar abaixo e deixou quatorze mortos. Ele planeja atacar a guilda em breve.
As tabernas mais conhecidas são a Caneca de Mutina, a Cerveja Assombrada e a Bardos a Bordo, onde se juntam os bardos da região.$t$, $t$Diz a lenda que Larda guarda num salão subterrâneo mais de cinquenta tesouros mágicos.
Do patriarca de Maira se diz que é corrupto e imoral, que vende as relíquias da catedral, que trocou os deuses de Tagmar por Rikutatis, um dos treze Príncipes Demônios, e que derruba alas inteiras do templo atrás de um compartimento secreto onde estaria a magia que afasta demônios e mortos-vivos daquele chão.$t$, false),
($t$litoria-nova$t$, $t$Litória Nova$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Marlom, político hábil e carismático$t$, NULL, NULL, $t$Continuação de Litória na margem norte do Rio Lara, que pelo tratado é terra de Filanti. Os moradores, quase todos humanos, se dizem maranenses e não pagam os impostos que Filanti cobra. Marlom tem conseguido evitar o pior.
Ainda assim há vandalismo, casas arrombadas e gente morta por feras que se julgavam sumidas da região, e muitos põem a culpa no governo de Filanti. Os únicos elfos da cidade são doze elfos dourados de uma expedição de Runa, em Portis, que estão aqui há uns seis meses.
Há duas tabernas abertas e três em obra. A Bela Marana é de Madame Lúcia e das filhas Maria, Joana e Lucípide, famosa pelas apresentações desta última, entre luzes e estouros que tiram o sono dos vizinhos. A Sangue em Garrafas, de Lomungo Pofi, vive em reforma por causa das brigas de todo dia, em que o dono costuma entrar.$t$, $t$Há quem jure que as feras são assassinos de Filanti disfarçados por ilusão. E muitos acham que Lucípide é maga ilusionista e usa a arte para atrair fregueses.$t$, false),
($t$pechara$t$, $t$Pechara$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Carlos Moldi, prefeito$t$, NULL, $t$Serve de parada para quem viaja ao sul do reino.$t$, $t$Cidade pequena, perto do centro de Filanti. O prefeito, Carlos Moldi, é conhecido em todos os meios de sábios por tentar, há anos e sem sucesso, fundar uma universidade aqui. Sua biblioteca tem milhares de volumes.
Para atrair estudiosos, Moldi chegou a forjar ruínas perto da cidade. A farsa foi descoberta e ele caiu em desgraça. Agora achou ruínas verdadeiras e ninguém acredita nele. O povo gosta da sua administração, mas já não aguenta ouvir falar de universidade.
A única taberna respeitável é a Letras e Canecos, de que Moldi é sócio, com poucos fregueses fiéis e recitais de poesia.$t$, NULL, false),
($t$rapso$t$, $t$Rapso$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Um conselho de velhos lenhadores$t$, NULL, $t$Vive das madeiras nobres que, por estranho que pareça, se acumulam na borda da floresta. Vende sobretudo para Calisto e Litória Nova.$t$, $t$Vila de lenhadores na borda da Floresta de Gironde, governada por um conselho de velhos do ofício. Não tem taberna: tem uma confraria de bebida e música de graça, sustentada por todos os que trabalham.$t$, $t$Dizem que o conselho fez um trato com os elfos e gnomos de Gironde: eles deixam cortar árvores já quase mortas, desde que os humanos não entrem mais na mata, e as árvores amanhecem na borda, perto de Rapso, levadas por magia.$t$, false),
($t$verda$t$, $t$Verda$t$, $t$novo-reino-h24-d5e5e848$t$, false, NULL, $t$Disputada pelos gêmeos Larel e Darel Courim$t$, NULL, $t$As caravanas fogem da cidade, e o povo vive do pouco que planta e pesca.$t$, $t$Cidade de porto à beira do Denégrio, de tabernas e docas, onde atracavam navios de toda a costa do lago. Hoje está entregue ao caos, com as docas vazias e as ruas sem segurança.
Há quinze anos, o Barão Courim, rico e sem herdeiro, viu a esposa dar à luz dois meninos gêmeos e agradeceu a todos os deuses de que lembrava o nome. Com a morte do barão, Larel e Darel disputam a herança. Larel, calado e sombrio, ficou com o palácio, no norte da cidade; Darel, falante, cruel e sarcástico, domina o sul. Os dois se dizem senhores de Verda, e a briga já passou da política para as armas.
Os mercadores e alguns nobres pediram ajuda ao rei várias vezes, sem resposta, e muitos foram embora.$t$, $t$Hoje se diz que aquela gravidez foi obra de Plandis, porque só o deus da loucura faria de uma bênção uma maldição.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-gironde$t$, $t$Floresta de Gironde$t$, $t$novo-reino-h24-d5e5e848$t$, NULL, $t$Grande mata que cobre boa parte de Filanti e que nem os vizinhos conhecem. Aldeias como Puzial e cidades como Rapso vivem da madeira que tiram da borda. Não há trilha conhecida que a atravesse.
Tem fama de assombrada. Lá dentro viveriam os Ferais, lobos gigantescos que atacam quem se embrenha demais. Os poucos que entram e voltam saem loucos, falando de vozes e de criaturas fantásticas. Os lobos cinzentos de Filanti que atravessam a mata e descem para Marana vêm daqui.$t$, $t$Dizem que elfos e gnomos vivem em Gironde e fizeram trato com os lenhadores de Rapso.$t$, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$chats$t$ WHERE slug = $t$novo-reino-h24-d5e5e848$t$ AND capital IS NULL;

-- ── águas (locais sem reino) ──
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$mar-do-norte$t$, $t$Mar do Norte$t$, NULL, NULL, $t$Mar que banha Saravossa, a costa de Calco e de Conti e as Cidades-Estado de Pino, Novo Porto e Torbel. Nele desembocam rios que descem da Muralha dos Deuses.
É morada da gigantesca serpente marinha. Piratas roubam mercadorias valiosas por toda a sua extensão e as vendem em Porto Livre.$t$, NULL, false),
($t$mar-da-morte$t$, $t$Mar da Morte$t$, NULL, NULL, $t$Mar a oeste de Tagmar, onde desemboca o Rio Estil, que nasce nos Montes Skorpios. É cheio de recifes; o maior e mais conhecido é o Recife dos Afogados, ao sul.
Como em todo mar de Tagmar, não há instrumento de rumo bom o bastante para navegar longe da costa: um grau de desvio pode significar uma vida à deriva ou uma viagem sem volta.$t$, NULL, false),
($t$recife-dos-afogados$t$, $t$Recife dos Afogados$t$, NULL, NULL, $t$O maior e mais conhecido dos recifes do Mar da Morte, no sul daquele mar. Logo abaixo dele fica a Baía de Liem.$t$, NULL, false),
($t$baia-de-liem$t$, $t$Baía de Liem$t$, NULL, NULL, $t$Baía ao sul do Recife dos Afogados, junto às terras de Lar. É lar de sereias exóticas e mortais.$t$, NULL, false),
($t$estreito-das-serpentes$t$, $t$Estreito das Serpentes$t$, NULL, NULL, $t$Passagem de mar na costa oeste, ao norte do Recife dos Afogados, entre o Mar da Morte e as montanhas que descem para Lar.$t$, NULL, false),
($t$mar-de-sargacos$t$, $t$Mar de Sargaços$t$, NULL, NULL, $t$Mar a oeste, além dos recifes das Terras Selvagens. Não se tem notícia de ninguém que tenha voltado de suas águas.$t$, NULL, false),
($t$mar-gelado$t$, $t$Mar Gelado$t$, NULL, NULL, $t$Mar do sudeste, que banha as Geleiras das Terras Selvagens e as Planícies Geladas de Enoar, salpicado de blocos de gelo.$t$, NULL, false),
($t$mar-de-suz$t$, $t$Mar de Suz$t$, NULL, NULL, $t$Mar do extremo sul, onde desembocam o Rio Lui-Rem, o Rio Ceris e o Rio Gendar, que descem da Cadeia Ergoniana. Ao sul, longe da costa, fica o arquipélago de Galpas.$t$, $t$Contam que Galpas era habitada por anões. Hoje os pescadores falam de seres estranhos por lá, que chamam de detritões.$t$, false),
($t$recifes-de-gandara$t$, $t$Recifes de Gandara$t$, NULL, NULL, $t$Barreira de recifes no norte da costa de Porto Livre, a mais traiçoeira do Mundo Conhecido. Só a atravessam navegadores que conhecem o lugar.$t$, NULL, false),
($t$recifes-do-tubarao$t$, $t$Recifes do Tubarão$t$, NULL, NULL, $t$Barreira de recifes no sul da costa de Porto Livre. Com os Recifes de Gandara, faz do litoral porto-livrense o mais perigoso que se conhece.$t$, $t$Dizem que Luna planejava retomar as terras de Porto Livre por um caminho seguro através destes recifes, largo o bastante para passar uma esquadra inteira sem ser vista.$t$, false)
ON CONFLICT (slug) DO NOTHING;

-- Lago Denégrio: de reino a local, com o texto que já tinha.
INSERT INTO public.locais (slug, nome, reino, populacao, imagem, descricao, rumores, compartilhado)
SELECT $t$lago-denegrio$t$, nome, NULL, NULL, NULL, descricao, NULLIF(rumores, ''), COALESCE(compartilhado, false)
FROM public.reinos WHERE slug = $t$novo-reino-h13-74c1b7c8$t$
ON CONFLICT (slug) DO NOTHING;

-- Ilha dos Corvos: de cidade a local.
INSERT INTO public.locais (slug, nome, reino, populacao, imagem, descricao, rumores, compartilhado)
SELECT $t$ilha-dos-corvos$t$, nome, NULL, populacao, imagem, descricao, rumores, COALESCE(compartilhado, false)
FROM public.cidades WHERE slug = $t$nova-cidade-h13-ecbf1062$t$
ON CONFLICT (slug) DO NOTHING;

-- Marcadores do mapa (mundo e mesa 24): cidade -> local.
UPDATE public.catalogo_mundo m SET dados = jsonb_set(m.dados, '{lugares}', (
  SELECT jsonb_agg(CASE WHEN l->>'ficha' = 'nova-cidade-h13-ecbf1062'
    THEN l || jsonb_build_object('tipo', 'local', 'ficha', 'ilha-dos-corvos') ELSE l END)
  FROM jsonb_array_elements(m.dados->'lugares') l))
WHERE m.tipo = 'mapa' AND m.dados::text LIKE '%nova-cidade-h13-ecbf1062%';
UPDATE public.mapas_mesa m SET dados = jsonb_set(m.dados, '{lugares}', (
  SELECT jsonb_agg(CASE WHEN l->>'ficha' = 'nova-cidade-h13-ecbf1062'
    THEN l || jsonb_build_object('tipo', 'local', 'ficha', 'ilha-dos-corvos') ELSE l END)
  FROM jsonb_array_elements(m.dados->'lugares') l))
WHERE m.dados::text LIKE '%nova-cidade-h13-ecbf1062%';

-- Mesa 13: o lago sai dos reinos e entra nos locais; a chave de acesso troca de tipo.
UPDATE public.historias h SET
  reino_ids = array_remove(h.reino_ids, 'novo-reino-h13-74c1b7c8'),
  local_ids = CASE WHEN 'lago-denegrio' = ANY(COALESCE(h.local_ids, '{}')) THEN h.local_ids ELSE array_append(COALESCE(h.local_ids, '{}'), 'lago-denegrio') END
WHERE 'novo-reino-h13-74c1b7c8' = ANY(h.reino_ids);
UPDATE public.historias h SET reino_ids = array_remove(h.reino_ids, 'novo-reino-h13-0fcc2f2a')
WHERE 'novo-reino-h13-0fcc2f2a' = ANY(h.reino_ids);
UPDATE public.historias h SET lore_acesso_pj = (
  SELECT jsonb_object_agg(CASE WHEN e.key = 'reino:novo-reino-h13-74c1b7c8' THEN 'local:lago-denegrio' ELSE e.key END, e.value)
  FROM jsonb_each(h.lore_acesso_pj) e)
WHERE h.lore_acesso_pj ? 'reino:novo-reino-h13-74c1b7c8';

DELETE FROM public.cidades WHERE slug = $t$nova-cidade-h13-ecbf1062$t$;
DELETE FROM public.reinos WHERE slug IN ($t$novo-reino-h13-74c1b7c8$t$, $t$novo-reino-h13-0fcc2f2a$t$);

COMMIT;
